from datetime import datetime
from decimal import Decimal


class DomainError(Exception):
    """Базовое доменное исключение транспортной системы."""
    pass


class InsufficientFundsError(DomainError):
    """Недостаточно средств на балансе карты."""
    pass


class CardBlockedError(DomainError):
    """Операция отклонена: карта заблокирована."""
    pass


class TicketAlreadyUsedError(DomainError):
    """Билет уже был использован ранее."""
    pass


class TicketExpiredError(DomainError):
    """Срок действия билета истек."""
    pass


class TransitCard:
    """Транспортная карта пассажира (Onay / Avtobys)."""

    def __init__(self, card_id: str, balance: Decimal = Decimal("0.00"), is_blocked: bool = False):
        bal = Decimal(str(balance))
        if bal < Decimal("0.00"):
            raise ValueError("Начальный баланс не может быть отрицательным")
        self._card_id = str(card_id)
        self._balance = bal
        self._is_blocked = bool(is_blocked)

    @property
    def card_id(self) -> str:
        return self._card_id

    @property
    def balance(self) -> Decimal:
        return self._balance

    @property
    def is_blocked(self) -> bool:
        return self._is_blocked

    def deposit(self, amount: Decimal) -> None:
        amt = Decimal(str(amount))
        if amt <= Decimal("0.00"):
            raise ValueError("Сумма пополнения должна быть строго больше нуля")
        if self._is_blocked:
            raise CardBlockedError("Невозможно пополнить заблокированную карту")
        self._balance += amt

    def pay(self, fare: Decimal) -> None:
        f = Decimal(str(fare))
        if f <= Decimal("0.00"):
            raise ValueError("Стоимость проезда должна быть строго больше нуля")
        if self._is_blocked:
            raise CardBlockedError("Невозможно оплатить проезд заблокированной картой")
        if self._balance < f:
            raise InsufficientFundsError(f"Недостаточно средств: баланс {self._balance}, требуется {f}")
        self._balance -= f

    def block(self) -> None:
        self._is_blocked = True

    def unblock(self) -> None:
        self._is_blocked = False


class SingleTripTicket:
    """Разовый QR-билет с фиксированным сроком действия."""

    def __init__(self, ticket_id: str, valid_until: datetime, price: Decimal = Decimal("120.00"), is_used: bool = False):
        pr = Decimal(str(price))
        if pr <= Decimal("0.00"):
            raise ValueError("Цена билета должна быть строго больше нуля")
        self._ticket_id = str(ticket_id)
        self._valid_until = valid_until
        self._price = pr
        self._is_used = bool(is_used)

    @property
    def ticket_id(self) -> str:
        return self._ticket_id

    @property
    def price(self) -> Decimal:
        return self._price

    @property
    def valid_until(self) -> datetime:
        return self._valid_until

    @property
    def is_used(self) -> bool:
        return self._is_used

    def validate(self, current_time: datetime) -> None:
        if self._is_used:
            raise TicketAlreadyUsedError("Билет уже был использован")
        if current_time > self._valid_until:
            raise TicketExpiredError("Срок действия билета истек")
        self._is_used = True
